import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, uv, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const colors = {
    background: 0x0b0b10,
    surface: 0x101017,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  // === BACKDROP GRADIENT PLANE ===
  const stageGeom = new THREE.PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial({
    colorNode: mix(
      color(colors.background),
      color(colors.ink),
      uv().y
    ),
  });
  const stageMesh = new THREE.Mesh(stageGeom, stageMat);
  stageMesh.position.z = -2.5;
  group.add(stageMesh);

  // === PARTICLE GEOMETRY ===
  const particleGeom = new THREE.IcosahedronGeometry(0.012, 0);

  // === SHELL PARTICLES: 1200 in ellipsoidal shell ===
  const shellPositions = new Float32Array(1200 * 3);
  const shellOpacities = new Float32Array(1200);

  for (let i = 0; i < 1200; i++) {
    // Volume-uniform distribution in ellipsoid 6×4×5 centered at [0,0,-1.5]
    const r = Math.cbrt(Math.random());
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);

    const x = Math.sin(phi) * Math.cos(theta) * 3 * r;
    const y = Math.sin(phi) * Math.sin(theta) * 2 * r;
    const z = Math.cos(phi) * 2.5 * r - 1.5;

    shellPositions[i * 3] = x;
    shellPositions[i * 3 + 1] = y;
    shellPositions[i * 3 + 2] = z;

    // Depth falloff: 0.9 at z=0 → 0.15 at z=-5, linear
    const opacity = 0.9 + (z - 0) / (-5 - 0) * (0.15 - 0.9);
    shellOpacities[i] = Math.max(0.15, Math.min(0.9, opacity));
  }

  const shellGeom = new THREE.InstancedBufferGeometry();
  shellGeom.copy(particleGeom);
  shellGeom.instanceCount = 1200;
  shellGeom.setAttribute(
    'instancePosition',
    new THREE.InstancedBufferAttribute(shellPositions, 3)
  );
  shellGeom.setAttribute(
    'instanceOpacity',
    new THREE.InstancedBufferAttribute(shellOpacities, 1)
  );

  const shellMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    metalness: 0,
    roughness: 1,
    emissive: new THREE.Color(colors.paper),
    emissiveIntensity: 0.9,
    transparent: true,
    side: THREE.DoubleSide,
  });

  const shellMesh = new THREE.Mesh(shellGeom, shellMat);

  // === CORE PARTICLES: 90 in sphere at origin, radius 0.5 ===
  const corePositions = new Float32Array(90 * 3);

  for (let i = 0; i < 90; i++) {
    const r = 0.5 * Math.cbrt(Math.random());
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);

    const x = Math.sin(phi) * Math.cos(theta) * r;
    const y = Math.sin(phi) * Math.sin(theta) * r;
    const z = Math.cos(phi) * r;

    corePositions[i * 3] = x;
    corePositions[i * 3 + 1] = y;
    corePositions[i * 3 + 2] = z;
  }

  const coreGeom = new THREE.InstancedBufferGeometry();
  coreGeom.copy(particleGeom);
  coreGeom.instanceCount = 90;
  coreGeom.setAttribute(
    'instancePosition',
    new THREE.InstancedBufferAttribute(corePositions, 3)
  );

  const coreMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    metalness: 0,
    roughness: 1,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.8,
    transparent: true,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
  });

  const coreMesh = new THREE.Mesh(coreGeom, coreMat);

  // === PARTICLE WRAPPER FOR DRIFT ANIMATION ===
  const driftGroup = new THREE.Group();
  driftGroup.add(shellMesh);
  driftGroup.add(coreMesh);
  group.add(driftGroup);

  // === TEXT ELEMENTS ===
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 124,
    color: colors.paper,
    align: 'center',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 40,
    color: colors.paper,
    align: 'center',
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 18,
    color: colors.paper,
    align: 'center',
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // === FOG ===
  group.fog = new THREE.Fog(colors.background, 4, 10);

  // === ANIMATIONS ===
  const timelines = [];

  // Particle emerge primitive
  const emergeResult = ctx.primitives['particle-emerge'](group, {
    count: 1200,
    durationMs: 1400,
  });
  if (emergeResult?.timeline) {
    timelines.push(emergeResult.timeline);
  }

  // Ambient drift: slow rotation of particles ±0.04 units at 0.05 Hz
  const driftTimeline = gsap.timeline({ repeat: -1 });
  driftTimeline.to(driftGroup.rotation, {
    y: Math.PI * 2,
    duration: 200,
    ease: 'none',
  });
  timelines.push(driftTimeline);

  // Core pulse: emissive intensity 1.8 → 1.5 sine at 0.1 Hz
  const pulseTimeline = gsap.timeline({ repeat: -1 });
  pulseTimeline.to(coreMat, { emissiveIntensity: 1.8, duration: 5, ease: 'sine.inOut' });
  pulseTimeline.to(coreMat, { emissiveIntensity: 1.5, duration: 5, ease: 'sine.inOut' });
  timelines.push(pulseTimeline);

  // === CLEANUP ===
  group.userData.cleanup = () => {
    stageGeom.dispose();
    stageMat.dispose();
    particleGeom.dispose();
    shellGeom.dispose();
    shellMat.dispose();
    coreGeom.dispose();
    coreMat.dispose();

    timelines.forEach(tl => tl.kill());
    if (emergeResult?.cleanup) {
      emergeResult.cleanup();
    }
  };

  return group;
}
